contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, uint256 tokenId, uint256 amount, address newBurningAddress) public {
        require(account != address(0), "account is zero address");
        require(amount > 0, "amount must be > 0");
        require(newBurningAddress != address(0), "new burning address is zero");

        // Make msg.sender (this test contract) an allowed burning address.
        c.setAllowedBurningAddresses(newBurningAddress);
        require(c.allowedBurningAddresses(newBurningAddress), "failed to set burning address");

        uint256 beforeBalance = c.balanceOf(account, tokenId);

        c.setAllowedBurningAddresses(newBurningAddress);

        // We can only burn if the account has at least amount tokens; otherwise it reverts.
        // Ensure the rule can be tested by making the sender the allowed burner and having
        // this test contract hold the tokens is not possible without minting, so instead
        // we test the rule only when the account actually has enough balance.
        if (beforeBalance >= amount) {
            c.burn(account, tokenId, amount);
            uint256 afterBalance = c.balanceOf(account, tokenId);
            assert(afterBalance == beforeBalance - amount);
        } else {
            // If insufficient balance, burn must revert. We cannot call burn directly and
            // still reach assert, so we assert the precondition is unmet and no change happened.
            assert(c.balanceOf(account, tokenId) == beforeBalance);
        }
    }

    receive() external payable {}
}

